head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick = function(e) {
    dd++
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var param1 = {
        "aa": "123"
    };
    var paramData = {
        parentPopupId: "",
        rowData: dlt_memberList.getRowJSON(0)
    };
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: paramData, // 전달 데이터 객체. 
        name: "paramData" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다. 
    };
    var opts = {
        "id": "popup_wframe1" + dd,
        "type": "window",
        "width": "700px",
        "height": "250px",
        "top": 150,
        "left": 150,
        "popupName": "wframe_Popup1" + dd,
        modal: true,
        // useModalDisable:true,
        useModalStack: true,
        "useIFrame": true,
        "dataObject": dataObj,
        "title": "focusTest",
        "alwaysOnTop": true,
        "frameMode": "wframe",
        useATagTitle: true,
        useATagBtn: true
    };
    //$w.openPopup("popup_wframe1.xml", opts, param1,null );
    $w.openPopup("gridView_senseReader_WEFF-579_(WSQ-3947)_sub2.xml", opts);
    //alert("[Open popup_wframe1]");
    //popup_wframe1.focus();
};
scwin.fn_openPopup = function() {
    debugger;
    idx++
    var options = {
        id: "popup1" + idx,
        //type : "window",
        type: "layer",
        //type : "iframe",   
        width: "700px",
        height: "300px",
        top: 150,
        left: 150,
        popupName: "TestPage1" + idx,
        modal: false,
        useIFrame: true,
        closeAction: "scwin.closePop",
        modal: true,
        useModalDisable: true,
        useModalStack: true,
        useATagTitle: true,
        //			  	
        //			  fullscreen:false,
        //			  useQueryString : false,
        //	          resizable : false, 
        //	          status : false, 
        //	          menubar : false,
        //	          scrollbars : false, 
        //	          title : false,
        //	          xml: "<FORM>한글입니다</FORM>",
        useATagBtn: true
        // dataObject : {type:"json", data: dataList1, name: "param1" }	          
    };
    if (idx > 3) {
        options.useModalStack = true;
    } else {
        //[default: false] 여러 개의 팝업을 생성할 경우, 제일 마지막에 표시되는 팝업만 
        // 활성화. (true: 마지막 팝업만 활성화. false: 모든 팝업을 활성화.)
        options.useModalStack = false;
    }
    pop = $w.openPopup("/ground/test.xml", options);
    //return 
    //popup1+idx.focus();
};
scwin.closePop = function() {
    alert("팝업닫힘");
    return true;
};
scwin.iframe_pop_btn_onclick = function(e) {
    scwin.fn_openPopup();
};
scwin.local1_onkeydown = function(e) {
    debugger;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.dd = 0;
    var pop;
    // dataList1.setData([1,2,3]);
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    window.idx = 0;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
